const slugToIconMap = {
  active: {
    icon: 'FaCircleCheck',
    color: tenantTheme['success-color'],
  },
  pending: {
    icon: 'RequestedStateIcon',
    color: tenantTheme['warning-color'],
  },
  expired: {
    icon: 'MdError',
    color: 'red',
  },
  rejected: {
    icon: 'MdCancel',
    color: 'red',
  },
  eligible: {
    icon: 'EligibleIcon',
    color: tenantTheme['success-color'],
  },
};

const renderTruCheckIcon = (slug) => {
  const iconData = slug ? slugToIconMap?.[slug] : slugToIconMap?.['eligible'];
  return (
    <Icon
      icon={iconData?.icon}
      style={{
        color: iconData?.color,
        position: 'absolute',
        insetBlockEnd: 0,
        insetInlineEnd: 0,
      }}
    />
  );
};

export const TrucheckSubIcon = ({ iconSlug }) => (
  <HasVerifiedCheck>
    <TruCheckIcon size={18} style={{ marginInlineEnd: '6px' }} />
    {renderTruCheckIcon(iconSlug)}
  </HasVerifiedCheck>
);

